    adcs_mat3_t B = {{{0}}};
    double k[4][4] = {{0}};
    double v[4] = {1.0, 0.0, 0.0, 0.0};
    double next[4];
    double sigma, z[3];
    double weight_sum = 0.0;
    size_t i, j, n, iter;

    if ((b == NULL) || (r == NULL) || (w == NULL) || (out == NULL)) {
        if (out != NULL) {
            *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        }
        return ADCS_E_NULL;
    }
    if ((n < 2U) || (n > 32U)) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }
    for (i = 0; i < n; i++) {
        adcs_vec3_t bn, rn;
        adcs_mat3_t o;
        if ((!isfinite(w[i])) || (w[i] <= 0.0) ||
            (!adcs_is_finite_vec3(&b[i])) || (!adcs_is_finite_vec3(&r[i])) ||
            (adcs_vec3_normalize(&b[i], ADCS_EPS_NORM, &bn) != ADCS_OK) ||
            (adcs_vec3_normalize(&r[i], ADCS_EPS_NORM, &rn) != ADCS_OK)) {
            *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }
        weight_sum += w[i];
        o = adcs_mat3_outer(&bn, &rn);
        for (j = 0; j < 3; j++) {
            size_t c;
            for (c = 0; c < 3; c++) {
                B.m[j][c] += w[i] * o.m[j][c];
            }
        }
    }
    sigma = B.m[0][0] + B.m[1][1] + B.m[2][2];
    z[0] = B.m[1][2] - B.m[2][1];
    z[1] = B.m[2][0] - B.m[0][2];
    z[2] = B.m[0][1] - B.m[1][0];
    k[0][0] = sigma;
    for (i = 0; i < 3; i++) {
        k[0][i + 1] = z[i];
        k[i + 1][0] = z[i];
        for (j = 0; j < 3; j++) {
            k[i + 1][j + 1] = B.m[i][j] + B.m[j][i] - ((i == j) ? sigma : 0.0);
        }
    }
    for (i = 0; i < 4; i++) {
        k[i][i] += weight_sum;
    }
    for (iter = 0; iter < ADCS_MAX_ITERATIONS; iter++) {
        double nrm = 0.0;
        double diff = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] = 0.0;
            for (j = 0; j < 4; j++) {
                next[i] += k[i][j] * v[j];
            }
            nrm += next[i] * next[i];
        }
        nrm = sqrt(nrm);
        if (nrm <= ADCS_EPS_QUAT) {
            *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
            return ADCS_E_DEGENERATE;
        }
        for (i = 0; i < 4; i++) {
            next[i] /= nrm;
            diff += fabs(next[i] - v[i]);
            v[i] = next[i];
        }
        if (diff < 1.0e-13) {
            break;
        }
    }
    if (iter >= ADCS_MAX_ITERATIONS) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_NO_CONVERGENCE;
    }
    *out = (adcs_quat_t){v[0], v[1], v[2], v[3]};
    if (out->w < 0.0) {
        out->w = -out->w;
        out->x = -out->x;
        out->y = -out->y;
        out->z = -out->z;
    }
    return ADCS_OK;
}

